columns.script:
const value = undefined;
const key = '';
// the rules, in order: the first whose condition holds decides the cell
const rules = [
  // rule 1: status equals 'running'
  {
    when: function (data, row, vars, value, key) {
      return (String(row["status"] ?? '') === "running");
    },
    text: "Update",
    textColumn: "status",
    class: "nim-btn-table btn-outline-success"
  }
];
const vars = data.var ?? {};
const row = data.row ?? {};
const m = rules.find(rule => {
  try {
    return !!rule.when(data, row, vars, value, key);
  } catch (err) {
    return false; // a condition that fails for a row does not hold
  }
});
// the text of the rule, else the value of its column
const mText = m ? (m.text || (m.textColumn ? String(row[m.textColumn] ?? '') : '')) : '';
if (!m) {
  return {}; // no rule holds: no button
}
return {
  "type": "button",
  "class": m.class,
  "icon": m.icon ? { name: m.icon, colorPrimaryOpacity: 1, colorSecondaryOpacity: 0 } : undefined,
  "text": mText,
  "event": m.event
};

